return {
  apply(ctx) {
    const sub = ctx.get('subprocess')
    const fs = ctx.get('fs')
    const WS = 'G:\\harness-organized'
    const PET = WS + '\\scripts\\desktop-pet.ps1'
    const PID_FILE = WS + '\\temp\\desktop-pet.pid'
    const DATA_FILE = WS + '\\temp\\desktop-pet-data.json'
    const STOP_FILE = WS + '\\temp\\desktop-pet-stop.flag'
    let handle = null
    let startedAt = 0

    const spawnArgs = (extra) => ({
      argv: ['powershell.exe', '-NoProfile', '-ExecutionPolicy', 'Bypass', ...extra],
      cwd: WS,
      stdio: { stdin: 'ignore', stdout: 'ignore', stderr: 'ignore' },
      graceMs: 2000,
    })

    const startPet = () => {
      if (handle) return { running: true, pid: handle.pid }
      try {
        handle = sub.spawn(spawnArgs(['-File', PET]))
        startedAt = Date.now()
        const h = handle
        h.done.then(() => { if (handle === h) handle = null }).catch(() => { if (handle === h) handle = null })
        return { running: true, pid: h.pid }
      } catch (e) {
        return { running: false, error: String((e && e.message) || e) }
      }
    }

    const stopPet = () => {
      if (handle) { try { handle.terminate() } catch (e) {} handle = null }
      try {
        sub.spawn(spawnArgs(['-Command', 'Set-Content -Path "' + STOP_FILE + '" -Value stop']))
      } catch (e) {}
      return { stopped: true }
    }

    ctx.effect(() => {
      const r = startPet()
      if (!r.running) console.error('pet start failed: ' + JSON.stringify(r))
      return () => { stopPet() }
    })

    const readJson = async (file) => {
      try {
        const t = await fs.resolve(file)
        const info = await fs.stat(t)
        if (!info) return null
        return JSON.parse(await fs.readText(t))
      } catch (e) { return null }
    }

    const readPid = async () => {
      try {
        const t = await fs.resolve(PID_FILE)
        const info = await fs.stat(t)
        if (!info) return null
        const n = parseInt((await fs.readText(t)).trim(), 10)
        return Number.isFinite(n) && n > 0 ? n : null
      } catch (e) { return null }
    }

    harness.handle('pet-status', async () => {
      const pid = await readPid()
      return { running: !!handle || !!pid, spawned: !!handle, pid: handle ? handle.pid : pid, startedAt }
    })
    harness.handle('pet-temps', async () => readJson(DATA_FILE))
    harness.handle('pet-stop', async () => stopPet())
    harness.handle('pet-start', async () => startPet())
  },
}

client:
return {
  inject: ['timer'],
  apply(ctx) {
    const slots = ctx.get('slots')
    if (slots === undefined) return

    styles.insert(`
      .dsh-pet-card { border: 1px solid #D9C6F0; border-radius: 14px; background: linear-gradient(135deg, #F7F2FC 0%, #E9DDF6 100%); padding: 12px 14px; font-family: 'Microsoft YaHei UI', 'Segoe UI', sans-serif; max-width: 420px; }
      .dsh-pet-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 10px; }
      .dsh-pet-title { font-size: 14px; font-weight: 700; color: #5E35B1; }
      .dsh-pet-badge { font-size: 11px; color: #fff; border-radius: 10px; padding: 2px 10px; }
      .dsh-pet-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 6px 16px; }
      .dsh-pet-row { display: flex; align-items: center; gap: 6px; }
      .dsh-pet-dot { width: 8px; height: 8px; border-radius: 50%; flex: none; }
      .dsh-pet-label { font-size: 12px; color: #7B4FA6; }
      .dsh-pet-value { font-size: 12.5px; font-weight: 700; margin-left: auto; }
      .dsh-pet-foot { display: flex; align-items: center; justify-content: space-between; margin-top: 10px; gap: 8px; }
      .dsh-pet-note { font-size: 10.5px; color: #A08CC4; }
      .dsh-pet-btn { font-size: 12px; border: 1px solid #B9A5E3; background: #fff; color: #6A1B9A; border-radius: 8px; padding: 4px 12px; cursor: pointer; }
      .dsh-pet-btn:hover { background: #F3EAFB; }
      .dsh-pet-btn-primary { background: #7B4FA6; color: #fff; border-color: #7B4FA6; }
      .dsh-pet-btn-primary:hover { background: #6A3FA0; }
    `)

    function TempRow(props) {
      return React.createElement('div', { className: 'dsh-pet-row' },
        React.createElement('span', { className: 'dsh-pet-dot', style: { background: props.color } }),
        React.createElement('span', { className: 'dsh-pet-label' }, props.label),
        React.createElement('span', { className: 'dsh-pet-value', style: { color: props.color } }, props.value),
      )
    }

    function PetCard() {
      const [status, setStatus] = React.useState(null)
      const [temps, setTemps] = React.useState(null)
      React.useEffect(() => {
        const tick = () => {
          host.call('pet-status').then(setStatus).catch(() => {})
          host.call('pet-temps').then(setTemps).catch(() => {})
        }
        tick()
        return ctx.interval(tick, 2000)
      }, [])
      const running = status ? !!status.running : true
      const fmtC = (v) => (v == null ? '--' : Number(v).toFixed(1) + '\u00B0C')
      const color = (v) => { if (v == null) return '#B9AEE0'; if (v >= 80) return '#C62828'; if (v >= 65) return '#E65100'; return '#8E4FC9' }
      const cpu = temps ? temps.cpu : null
      const mem = temps ? temps.mem : null
      const gpu = temps ? temps.gpu : null
      const nvme = temps ? temps.nvme : null
      const action = running
        ? React.createElement('button', { className: 'dsh-pet-btn', onClick: () => { host.call('pet-stop').then(() => setStatus({ running: false })).catch(() => {}) } }, '停止监控')
        : React.createElement('button', { className: 'dsh-pet-btn dsh-pet-btn-primary', onClick: () => { host.call('pet-start').then(() => setStatus({ running: true })).catch(() => {}) } }, '启动监控')
      return React.createElement('div', { className: 'dsh-pet-card' },
        React.createElement('div', { className: 'dsh-pet-head' },
          React.createElement('span', { className: 'dsh-pet-title' }, '安安热能监控'),
          React.createElement('span', { className: 'dsh-pet-badge', style: { background: running ? '#66BB6A' : '#BDBDBD' } }, running ? '运行中' : '已停止'),
        ),
        React.createElement('div', { className: 'dsh-pet-grid' },
          React.createElement(TempRow, { label: 'CPU 温度', value: fmtC(cpu), color: color(cpu) }),
          React.createElement(TempRow, { label: '内存 温度', value: fmtC(mem), color: color(mem) }),
          React.createElement(TempRow, { label: 'GPU 温度', value: fmtC(gpu), color: color(gpu) }),
          React.createElement(TempRow, { label: 'NVMe 固态', value: fmtC(nvme), color: color(nvme) }),
        ),
        React.createElement('div', { className: 'dsh-pet-foot' },
          React.createElement('span', { className: 'dsh-pet-note' }, '桌面萌宠悬停显示温度 · 硬件未暴露显示 --'),
          action,
        ),
      )
    }

    slots.inject('tool.view.cordis', () => slots.register(
      { name: 'tool.view.cordis', key: 'self' },
      () => React.createElement(PetCard, null),
    ))
  },
}
